import 'package:cloud_firestore/cloud_firestore.dart';
class FocusHistoryService{final FirebaseFirestore db;FocusHistoryService({FirebaseFirestore? firestore}):db=firestore??FirebaseFirestore.instance;Future<void> record(String u,{required String goalId,required String title,required int minutes})=>db.collection('users').doc(u).collection('focus_history').add({'goalId':goalId,'title':title,'minutes':minutes,'completedAt':FieldValue.serverTimestamp()});Stream<QuerySnapshot<Map<String,dynamic>>> watch(String u)=>db.collection('users').doc(u).collection('focus_history').orderBy('completedAt',descending:true).limit(100).snapshots();}